// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 nDeposits, uint256 amount) public {
        nDeposits = bound(nDeposits, 2, 50);
        amount = bound(amount, 0, 1e18);
        vm.deal(address(this), amount * nDeposits);
        for (uint256 i = 0; i < nDeposits; i++) {
            (bool ok, ) = address(c).call{value: amount}("");
            assertTrue(ok);
        }
        assertTrue(c.depositsCount() == nDeposits);
    }
}
